using System;using System.IO;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class ChestSeriesMemoryChecks {
 [Serializable]class Row{public string id,hash;public bool added,sameReference;public long beforeBytes,afterBytes,warmBytes;public int vertices,indices,stride;}
 [Serializable]class Report{public bool pass;public string error;public long oldBytes,newBytes,addedBytes,warmOldBytes,warmNewBytes,warmAddedBytes;public List<Row> rows=new List<Row>();}
 static string Arg(string k){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,k)+1];}
 static string Hash(Mesh m){using(var s=new MemoryStream()){using(var w=new BinaryWriter(s)){foreach(var p in m.vertices){w.Write(p.x);w.Write(p.y);w.Write(p.z);}foreach(var p in m.normals){w.Write(p.x);w.Write(p.y);w.Write(p.z);}foreach(var p in m.colors){w.Write(p.r);w.Write(p.g);w.Write(p.b);w.Write(p.a);}foreach(var p in m.uv){w.Write(p.x);w.Write(p.y);}foreach(var p in m.triangles)w.Write(p);w.Flush();return Convert.ToBase64String(SHA256.Create().ComputeHash(s.ToArray()));}}}
 public static void Run(){int code=0;var report=new Report();var output=Arg("-memory-output");Directory.CreateDirectory(output);try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
  var prior=MapSharedPropsBuilder.Build(Arg("-memory-before"));var next=MapSharedPropsBuilder.Build(Arg("-memory-after"));prior.root.SetActive(false);next.root.SetActive(false);
  var old=SmallPropsV1.Read(Path.Combine(Arg("-memory-before"),"small_props.json"));var data=SmallPropsV1.Read(Path.Combine(Arg("-memory-after"),"small_props.json"));if(old.assets.Length!=37||data.assets.Length!=43)throw new Exception("Expected 37 frozen / 43 current assets");
  var warm=new GameObject("All43MeshWarmup");int i=0;var oldIds=new HashSet<string>();foreach(var a in old.assets)oldIds.Add(a.id);
  foreach(var a in data.assets){var m=next.prefabs[a.id].GetComponent<MeshFilter>().sharedMesh;var row=new Row{id=a.id,added=!oldIds.Contains(a.id),hash=Hash(m),afterBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m),vertices=m.vertexCount,indices=m.triangles.Length,stride=m.GetVertexBufferStride(0)};
   if(!row.added){var before=prior.prefabs[a.id].GetComponent<MeshFilter>().sharedMesh;row.sameReference=before==m;row.beforeBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(before);if(!row.sameReference||row.hash!=Hash(before)||row.beforeBytes!=row.afterBytes)throw new Exception("Existing source/cache changed: "+a.id);report.oldBytes+=row.beforeBytes;}else report.addedBytes+=row.afterBytes;report.newBytes+=row.afterBytes;report.rows.Add(row);
   var o=(GameObject)PrefabUtility.InstantiatePrefab(next.prefabs[a.id],warm.transform);o.transform.position=new Vector3((i%8)*6,0,(i/8)*6);i++;
  }
  var renderers=warm.GetComponentsInChildren<Renderer>();var bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);var camera=new GameObject("All43 memory camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.farClipPlane=1000;camera.transform.position=bounds.center+Vector3.up*(Mathf.Max(bounds.size.x,bounds.size.z)*2+bounds.size.y);camera.transform.rotation=Quaternion.LookRotation(Vector3.down,Vector3.forward);camera.targetTexture=new RenderTexture(1000,800,24);camera.Render();camera.Render();
  foreach(var row in report.rows){row.warmBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(next.prefabs[row.id].GetComponent<MeshFilter>().sharedMesh);report.warmNewBytes+=row.warmBytes;if(row.added)report.warmAddedBytes+=row.warmBytes;else report.warmOldBytes+=row.warmBytes;}
  report.pass=true;
 }catch(Exception e){code=1;report.error=e.ToString();Debug.LogException(e);}finally{File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(code);}}
}
